interface State { void publish(Document doc); }

final class Draft implements State {
    public void publish(Document doc) { doc.setPhase(new Moderation()); }
}

final class Document {
    private State phase = new Draft();
    void setPhase(State s) { this.phase = s; }
    void publish() { phase.publish(this); }
}

sealed interface Phase permits Draft, Published {}
record Draft() implements Phase {}
record Published(int version) implements Phase {}

static Phase publish(Phase p) {
    return switch (p) {
        case Draft d -> new Published(1);
        case Published pv -> pv;      // exhaustive: no default arm needed
    };
}
